return $input.all().map(item => {
  const j = item.json || {};
  const raw = j.contentSnippet || j.content || j.description || j.summary || j.title || '';
  const contentSnippet = String(raw).replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
  const pubDate = j.isoDate || j.pubDate || j.pubdate || j.date || '';
  const link = j.link || '';
  // R1 -- ninguno de los dos nodos RSS (Cointelegraph, Investing.com) etiquetaba su fuente,
  // asi que las dos llegaban como 'RSS' generico y la atribucion visible que exige la
  // auditoria legal no podia decir CUAL fuente. Se deriva del dominio del propio link, sin
  // anadir un nodo nuevo al canvas.
  let fuente = j.fuente || '';
  if (!fuente) {
    if (/cftc\.gov/i.test(link)) fuente = 'CFTC';
    else if (/investing\.com/i.test(link)) fuente = 'Investing.com';
    else if (/federalreserve\.gov/i.test(link)) fuente = 'Reserva Federal';
    else if (/sec\.gov/i.test(link)) fuente = 'SEC';
  }
  return { json: {
    title: String(j.title || '').trim(),
    link: link,
    contentSnippet: contentSnippet,
    pubDate: pubDate,
    fuente: fuente
  }};
});

