let data = $json.output?.[0]?.content?.[0]?.text ?? $json.choices?.[0]?.message?.content ?? $json.message?.content ?? $json.text;
if (typeof data === 'string') {
  data = data.trim().replace(/^```json\s*/i, '').replace(/```\s*$/, '');
  data = JSON.parse(data);
}
if (!data || typeof data !== 'object') {
  data = {};
}
const feed = $('Normalizar Item').item.json || {};
const title = data.title || 'Sin titulo';
const slug = (data.slug || title).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const sentimentMap = { 'Bullish': 'bullish', 'Bearish': 'bearish', 'Neutro': 'neutral', 'bullish': 'bullish', 'bearish': 'bearish', 'neutral': 'neutral' };
const sentiment = sentimentMap[data.sentiment] || 'neutral';
const categoryMap = { 'criptomonedas': 1, 'forex': 2, 'materias-primas': 3, 'acciones': 4 };
const categoryId = categoryMap[data.category] || 1;
const originalLocale = data.original_locale === 'en' ? 'en' : 'es';
// F3.1 -- GPT se pasa a menudo del maximo (salieron 872 y 923 sobre 750): en vez de mandar a borrador
// un articulo valido, se quitan bloques completos del final (nunca se corta a mitad de frase). Si un
// solo bloque ya supera el limite, se deja tal cual y el checklist lo rechazara.
const LIMITE = 750;
const textoDe = (html) => html.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
const recortarHtml = (html) => {
  if (textoDe(html).length <= LIMITE) return html;
  const bloques = html.match(/<(p|h2|h3|blockquote|ul|ol)\b[^>]*>[\s\S]*?<\/\1>/gi);
  if (!bloques || bloques.length < 2) return html;
  while (bloques.length > 1 && textoDe(bloques.join('')).length > LIMITE) bloques.pop();
  while (bloques.length > 1 && /^<h[23]\b/i.test(bloques[bloques.length - 1])) bloques.pop();
  return bloques.join('');
};

const contentHtml = recortarHtml(data.content_html || '<p>Sin contenido</p>');
const plainText = contentHtml.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
const format = plainText.length < 350 ? 'brief' : 'article';
const wordCount = plainText.length > 0 ? plainText.split(' ').filter(Boolean).length : 0;
const readingTimeMinutes = Math.max(1, Math.ceil(wordCount / 200));
// R1 -- source_id mapea el nombre de fuente al id real de la tabla fuentes (verificado hoy:
// Cointelegraph=8, Investing.com=4). null si la fuente no esta en el registro, para no romper
// el insert con un id inventado.
const sourceIdMap = { 'CFTC': 11, 'Investing.com': 4, 'Reserva Federal': 9, 'SEC': 10 };
// Banderas y activos de la portada: solo lo que la plantilla sabe dibujar (si GPT inventa otro codigo, se descarta)
const BANDERAS_OK = new Set('US EU GB JP CN DE FR IT ES CA AU NZ CH MX BR AR CL CO PE VE IN ID KR TW HK SG TH MY PH VN TR RU UA PL SE NO DK NL BE PT IE AT GR ZA NG EG SA AE IL IR IQ QA KW PK BD CZ HU RO FI SY LY'.split(' '));
const ACTIVOS_OK = new Set('BTC ETH SOL XRP ADA DOGE BNB DOT AVAX LINK LTC UNI ATOM POL USDT USDC TRX XLM BCH ETC XAUUSD XAGUSD PLATINUM PALLADIUM COPPER WTI BRENT NG CORN WHEAT SUGAR COFFEE EURUSD GBPUSD USDJPY USDCHF USDCAD AUDUSD NZDUSD EURGBP EURJPY GBPJPY SPX NDX DJI DXY VIX US10Y DAX CAC40 FTSE NIKKEI HSI ESTX50'.split(' '));
const limpiarLista = (valor, permitidos, max) => {
  const lista = Array.isArray(valor) ? valor : typeof valor === 'string' ? valor.split(',') : [];
  const salida = [];
  for (const item of lista) {
    const codigo = String(item || '').trim().toUpperCase();
    if (permitidos.has(codigo) && !salida.includes(codigo)) salida.push(codigo);
    if (salida.length >= max) break;
  }
  return salida;
};
return [{ json: {
  original_locale: originalLocale,
  title: title,
  slug: slug,
  content_html: contentHtml,
  format: format,
  reading_time_minutes: readingTimeMinutes,
  sentiment: sentiment,
  category_id: categoryId,
  meta_description: data.meta_description || title,
  cover_flags: limpiarLista(data.cover_flags, BANDERAS_OK, 2),
  cover_assets: limpiarLista(data.cover_assets, ACTIVOS_OK, 2),
  prompt_imagen: data.prompt_imagen || '3D corporate financial illustration with candlestick charts and city skyline, dark background',
  source_url: feed.link || '',
  source_title: feed.title || '',
  source_id: sourceIdMap[feed.fuente] || null,
  fuente: feed.fuente || 'RSS'
}}];

const input = $input.first().json;
const scraped = (input.data && (input.data.markdown || input.data.content)) || input.markdown || '';
const feed = $('Normalizar Item').item.json || {};
const MAX_CHARS = 4000;

// F2.6 -- aun con onlyMainContent, Firecrawl trae ruido (publicidad, autor, fecha, titulo repetido,
// enlaces de comentarios, tickers de precios, imagenes) que se pagaba en tokens y podia empujar el
// final del articulo fuera del limite.
const vistas = new Set();
const lineas = String(scraped)
  .replace(/!\[[^\]]*\]\([^)]*\)/g, '')
  .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')
  .split('\n')
  .map((l) => l.trim())
  .filter((l) => {
    if (!l) return true;
    const b = l.toLowerCase().replace(/^#+\s*/, '');
    if (/^(advertisement|publicidad|anuncio)$/.test(b)) return false;
    if (/^(view all comments|ver todos los comentarios|comments|comentarios)\b/.test(b)) return false;
    if (/^(author|autor|by |por |published|publicado|updated|actualizado)\b/.test(b)) return false;
    if (/^(escrito por|revisado por|written by|reviewed by|edited by)\b/.test(b)) return false;
    if (/publicado\s*\d|published\s*\w{3,9}\.? \d/.test(b)) return false;
    if (/^(copiar enlace|copy link)/.test(b) || /^(share|compartir)\b/.test(b)) return false;
    if (/^(in this article|en este articulo|en este artículo):?$/.test(b)) return false;
    if (/^(stock markets|últimas noticias|ultimas noticias|cryptocurrency news|economy news|economy|forex news|commodities news|company news|earnings|market news|stock market news)$/.test(b)) return false;
    if (/^©/.test(b)) return false;
    if (/^[a-z0-9]{2,8}\$[\d.,]+/i.test(l)) return false;
    if (/^[A-Za-z0-9.&:_\\]{1,16}[+-]\d+(\.\d+)?%$/.test(l)) return false;
    if (/^[\d\s.,]+$/.test(b)) return false;
    if (vistas.has(b)) return false;
    vistas.add(b);
    return true;
  });
const clean = lineas.join('\n').replace(/\n{3,}/g, '\n\n').trim();
const fullContent = clean.length > 50 ? clean.slice(0, MAX_CHARS) : (feed.contentSnippet || '');

// F1.8 -- con menos de 200 caracteres de fuente GPT rellena con generalidades inventadas (§11.5).
if (fullContent.length < 200) {
  throw new Error('Contenido fuente insuficiente (' + fullContent.length + ' caracteres): Firecrawl fallo y el extracto RSS es demasiado corto.');
}
return [{ json: {
  title: feed.title || '',
  link: feed.link || '',
  fuente: feed.fuente || '',
  pubDate: feed.pubDate || '',
  fullContent: fullContent,
  contentSnippet: feed.contentSnippet || ''
}}];

